targets.expr:
count(
  (
    max by (namespace, container, target_name) (
      label_replace(
        label_replace(
          kube_pod_container_resource_requests{resource="cpu", cluster=~"$cluster", namespace=~"$namespace"}
          * on(pod, namespace, cluster) group_left(owner_name)
          max by (pod, namespace, cluster, owner_name) (kube_pod_owner{cluster=~"$cluster", namespace=~"$namespace"}),
          "workload", "$1", "owner_name", "^(.+?)(?:-[a-z0-9]{5,10})?$"
        ),
        "target_name", "$1", "workload", "(.*)"
      )
    )
    - on(namespace, container, target_name) 
    kube_vpa_container_recommendation_target_cpu{cluster=~"$cluster", namespace=~"$namespace"}
  ) > 0.01
) or vector(0)

